// ═══ orTimeout — fail on timeout (Java 9) ═══
CompletableFuture<String> cf = CompletableFuture
    .supplyAsync(() -> slowExternalCall())   // might take 30 seconds!
    .orTimeout(5, TimeUnit.SECONDS);         // fail after 5 seconds!
// If completes in 5s → normal result.
// If exceeds 5s → CompletionException(TimeoutException)!

try {
    String result = cf.join();
} catch (CompletionException e) {
    if (e.getCause() instanceof TimeoutException) {
        return "Service unavailable — try later";
    }
}

// ═══ completeOnTimeout — fallback on timeout (Java 9) ═══
CompletableFuture<Integer> scoreCF = CompletableFuture
    .supplyAsync(() -> callCreditBureau())     // might be slow!
    .completeOnTimeout(500, 5, TimeUnit.SECONDS); // fallback: 500 after 5s!
// If completes in 5s → real score.
// If exceeds 5s → 500 (cached/default score). No exception!
int score = scoreCF.join();  // always succeeds!

// ═══ BEFORE Java 9 — manual timeout ═══
CompletableFuture<String> cf2 = CompletableFuture.supplyAsync(() -> slowCall());
try {
    String result = cf2.get(5, TimeUnit.SECONDS);  // blocks with timeout
} catch (TimeoutException e) {
    cf2.cancel(true);  // attempt to cancel
    return "fallback";
}

// ═══ WHY TIMEOUTS ARE NON-OPTIONAL ═══
// External service: HTTP call to payment gateway
// Normal: 200ms. During outage: hangs FOREVER (TCP timeout = 300s default!)
// Without timeout:
//   Thread blocked 300 seconds → pool exhausted → all requests queued
//   → circuit breaker never triggers (no failure, just hanging)
//   → cascading failure → entire service DOWN!
// With timeout:
//   5-second timeout → TimeoutException after 5s → thread freed
//   → circuit breaker counts failure → opens → fast-fail
//   → service degraded but alive!

// ═══ CHAINING timeouts in pipeline ═══
CompletableFuture<String> result = CompletableFuture
    .supplyAsync(() -> fetchProfile(), ioPool)
    .orTimeout(3, TimeUnit.SECONDS)
    .thenCompose(profile -> fetchScore(profile))
    .orTimeout(5, TimeUnit.SECONDS)                // total 5s for both!
    .thenApply(score -> decide(score))
    .completeOnTimeout("PENDING", 10, TimeUnit.SECONDS)  // overall fallback
    .exceptionally(ex -> "ERROR");
