package com.bank.timeout;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;

class CFTimeoutTest {

    // ═══ orTimeout: TimeoutException on slow call ═══
    @Test
    void orTimeout_failsOnSlow() {
        CompletableFuture<String> cf = CompletableFuture.supplyAsync(() -> {
            try { Thread.sleep(5000); } catch (InterruptedException e) { }
            return "done";
        }).orTimeout(500, TimeUnit.MILLISECONDS);

        assertThatThrownBy(cf::join)
            .isInstanceOf(CompletionException.class)
            .hasCauseInstanceOf(TimeoutException.class);
    }

    // ═══ orTimeout: succeeds if fast enough ═══
    @Test
    void orTimeout_succeedsIfFast() {
        String result = CompletableFuture.supplyAsync(() -> {
            try { Thread.sleep(50); } catch (InterruptedException e) { }
            return "SETTLED";
        }).orTimeout(2, TimeUnit.SECONDS).join();

        assertThat(result).isEqualTo("SETTLED");
    }

    // ═══ completeOnTimeout: fallback on slow ═══
    @Test
    void completeOnTimeout_fallbackValue() {
        int score = CompletableFuture.supplyAsync(() -> {
            try { Thread.sleep(5000); } catch (InterruptedException e) { }
            return 750;
        }).completeOnTimeout(500, 500, TimeUnit.MILLISECONDS).join();

        assertThat(score).isEqualTo(500);  // fallback! Not 750!
    }

    // ═══ completeOnTimeout: real value if fast ═══
    @Test
    void completeOnTimeout_realValueIfFast() {
        int score = CompletableFuture.supplyAsync(() -> {
            try { Thread.sleep(50); } catch (InterruptedException e) { }
            return 750;
        }).completeOnTimeout(500, 2, TimeUnit.SECONDS).join();

        assertThat(score).isEqualTo(750);  // real value! Fast enough!
    }

    // ═══ Pipeline with timeouts ═══
    @Test
    void pipeline_withTimeouts() {
        String result = CompletableFuture
                .supplyAsync(() -> { sleep(50);
                return "PROFILE"; })
            .orTimeout(2, TimeUnit.SECONDS)
            .thenApply(profile -> profile + ":SCORE-750")
            .completeOnTimeout("PENDING", 5, TimeUnit.SECONDS)
            .exceptionally(ex -> "ERROR:" + ex.getMessage())
            .join();

        assertThat(result).isEqualTo("PROFILE:SCORE-750");
    }

    void sleep(long ms) { try { Thread.sleep(ms); } catch (InterruptedException e) {} }
}
